head.script:
///////// 2. 초기화 영역 /////////
            scwin.onpageload = function (e) {

                dma_search.set("formAuthId", $c.data.getParameter("authId"));

                // 시장구분코드
                const list = ["LD_MKT_TP_CD"];
                const params = {"cdEngNmList":list};

                // 시장구분 정보 조회
                $c.sbm.execute(sbm_ldMktTpCd, params);

                // 초기화
                pgl_list.hide();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.btn_search_onclick = function (e) {

                scwin.fnSearch("Y", 1);
            };

            scwin.sbx_page_onchange = function (info) {

                scwin.fnSearch("Y", 1);
            };

            scwin.pgl_list_onclick = function (index) {

                scwin.fnSearch("N", index);
            };

            scwin.btn_save_onclick = function (e) {

                let formAuthIdList = [];
                for (let i=0; i < dlt_list.getRowCount(); i++) {
                    if (dlt_list.getCellData(i, "CHK") === "1") {
                        // 이미 등록된 ID 체크 수정 필요
                        let params = {};
                        params.formAuthId = dma_search.get("formAuthId");
                        params.formCd = dlt_list.getCellData(i, "formCd");
                        params.formVer = dlt_list.getCellData(i, "formVer");

                        formAuthIdList.push(params);
                    }
                }

                // 등록 처리
                if (formAuthIdList.length > 0) {
                    $c.sbm.execute(sbm_save, formAuthIdList);
                } else {
                    $c.win.alert("등록할 서식을 체크 해주세요.");
                }
            };

            scwin.ibx_formKorNm_onkeyup = function (e) {

                if (e.key === "Enter") {                    
                    scwin.fnSearch("Y", 1);
                }
            };

            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_ldMktTpCd_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // select box 자동 생성
                    $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
                    // 조회
                    scwin.fnSearch("Y", 1);
                } else {
                    $c.win.alert(result.message);
                }
            };

            scwin.sbm_list_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    const obj = result.body;

                    const firstYn = dma_search.get("totalYn");
                    let totalCnt = 0;

                    // 최초 조회일 경우에만 전체 건수를 구하여 전역변수에 담는다.
                    if (firstYn === "Y") {
                        if (!$c.util.isEmpty(obj.totalCount)) {
                            tbx_totCnt.setValue($c.num.formatNumber(obj.totalCount));
                            totalCnt = parseInt(obj.totalCount) || 0;
                        }        

                        // 데이터가 있는 경우에만 페이지 리스트 표시
                        if (totalCnt > 0) { 
                            pgl_list.setCount(obj.totalPages);
                            pgl_list.show();
                        } else {
                            pgl_list.hide();
                        }            
                    }
                } else {
                    $c.win.alert(result.message); 
                }             
            };

            scwin.sbm_save_submitdone = async function (e) {

                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장 되었습니다.");

                    let params = {};
                    params.refreshYn = "Y";

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);
                }
            };

///////// 5. 일반/업무 함수 영역 /////////
            scwin.fnSearch = function (totYn, index) {

                dma_search.set("totalYn", totYn);
                dma_search.set("page", index);
                dma_search.set("size", sbx_page.getValue());

                // 조회 
                $c.sbm.execute(sbm_list, dma_search.getJSON());
            };
